var function_desc = "Feature introduction";
var qa1_a = "Is the website free?";
var qa1_q1 = "Not entirely free. To sustain long-term development, paid features are inevitable later, but you won't be forced to pay to use it; we try to strike a balance between free and paid.";
var qa1_q2 = "The project is open source and can be self-hosted.";
var qa2_a = "Can't type, pressing keys has no response?";
var qa3_a = "Where is the data? How to use it across multiple computers/devices?";
var qa3_q1 = "All user data is stored in the local browser. If you need to use Type Words on a different device or browser, you need to manually export and import the data.";
var qa3_q2 = "Settings -> Data Settings -> Export data on the original computer -> Send to the new computer via social app -> Import on the new computer";
var qa3_q3 = "An account system is under development.";
var qa4_a = "The website auto-plans too many words. How to change it?";
var qa4_q1 = "By default, the ratio of review words to new words is 1:4. If there are 40 new words, it will review 40 from the last session and 120 from earlier sessions (nearest to farthest).";
var qa4_q2 = "You can modify it via Settings -> Word Settings -> Review Ratio";
var qa5_a = "Does it take a long time to complete a study session? Is the process too lengthy?";
var qa5_q1 = "This is indeed a problem. A lengthy process can easily discourage people from memorizing words. I'm thinking about how to optimize the learning flow. If you have good suggestions, feel free to give feedback.";
var qa5_q2 = "Wrong words will be repeated. If it was just a typo, you can press the Tab key to skip when practicing again later. Since we can't tell whether it was a typo or the user really doesn't know it, all wrong words must be repeated until correct.";
var qa5_q3 = "During review, only words marked as 'not known' require dictation and spelling practice, which is reasonable. However, currently the same word may be reviewed N times.";
var qa5_q4 = "After the account system goes live, we will add the Ebbinghaus memory curve feature, and the planned review words will be smarter than now.";
var qa6_a = "Will the Ebbinghaus memory curve feature be added?";
var qa7_a = "Can I add words myself / create a custom dictionary / import my own words / modify word content?";
var qa7_q1 = "Yes. On the words screen, click 'Create Personal Dictionary'.";
var qa7_q2 = "After creation, on the dictionary detail page, click the 'Add Word' icon to add your own words.";
var qa7_q3 = "You can also click the 'Import' icon to import in bulk (must strictly follow the xlsx template format).";
var qa8_a = "Can I add articles myself / create custom books / import my own articles / modify article content?";
var qa8_q1 = "Yes, the steps are basically the same as adding words.";
var qa8_q2 = "On the articles screen, click 'Create Personal Book'.";
var qa8_q3 = "After creation, on the book detail page, click the 'Article Management' button at the top to add your own articles.";
var qa9_a = "How do I turn off the key sound?";
var qa9_q = "Settings -> General Settings -> Sound -> Key Sound, just turn it off.";
